    26→// newTestServer builds a Server with in-memory SQLite and mock content.
    27→func newTestServer(t *testing.T) *Server {
    28→	t.Helper()
    29→	// Use temp file so all connections share the same database (SQLite :memory: is per-connection)
    30→	dir := t.TempDir()
    31→	dbPath := filepath.Join(dir, "test.db")
    32→	cfg := database.Config{
    33→		DBType: "sqlite",
    34→		DBPath: dbPath,
    35→		Port:   1,
    36→	}
    37→	db, err := database.NewDatabase(cfg)
    38→	if err != nil {
    39→		t.Fatalf("NewDatabase: %v", err)
    40→	}
    41→	if err := db.InitSchema(cfg); err != nil {
    42→		t.Fatalf("InitSchema: %v", err)
    43→	}
    44→	seedTestDB(t, db)
    45→
    46→	content := fstest.MapFS{
    47→		"public_html/api-usage.html": {Data: []byte(`<html><body>__BASE_URL__ __API_ROOT__ __DISPLAY_HOST__ __ARCHIVE_ENABLED__ __ARCHIVE_ROUTE__ __ARCHIVE_FREQUENCY__</body></html>`), Mode: 0644},
    48→		"LICENSE":                     {Data: []byte("MIT License\nCopyright (c) 2015-present"), Mode: 0644},
    49→		"LICENSE.CC0":                 {Data: []byte("CC0 1.0 Universal"), Mode: 0644},
    50→	}
    51→
    52→	return NewServer(db, content, Config{
    53→		Domain:                "localhost:8765",
    54→		Port:                  8765,
    55→		DBType:                "sqlite",
    56→		AutoLocateDefault:     false,
    57→		APIDocsArchiveEnabled: true,
    58→		APIDocsArchiveRoute:   "/api/json/weekly.tgz",
    59→		APIDocsArchiveFrequency: "weekly",
    60→	}, nil)
    61→}
