    71→// seedTestDB inserts mock data for handler tests.
    72→func seedTestDB(t *testing.T, db *database.Database) {
    73→	t.Helper()
    74→	ctx := context.Background()
    75→
    76→	// tracks
    77→	_, err := db.DB.ExecContext(ctx, `INSERT INTO tracks (trackID) VALUES (?)`, testTrackID)
    78→	if err != nil {
    79→		t.Fatalf("seed tracks: %v", err)
    80→	}
    81→
    82→	// markers with has_spectrum
    83→	_, err = db.DB.ExecContext(ctx, `INSERT INTO markers (id, doseRate, date, lon, lat, countRate, zoom, speed, trackID, has_spectrum) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    84→		testMarkerID, 0.15, time.Now().Unix(), 139.7, 35.6, 10.0, 10, 0.0, testTrackID, 1)
    85→	if err != nil {
    86→		t.Fatalf("seed markers: %v", err)
    87→	}
    88→
    89→	// spectra
    90→	channelsJSON := `[0,1,2,3,4,5]`
    91→	calibrationJSON := `{"a":0,"b":1.5,"c":0}`
    92→	_, err = db.DB.ExecContext(ctx, `INSERT INTO spectra (marker_id, channels, channel_count, energy_min_kev, energy_max_kev, live_time_sec, real_time_sec, device_model, calibration, source_format, filename, raw_data, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    93→		testMarkerID, channelsJSON, 1024, 0, 3000, 60.0, 60.0, "RadiaCode-102", calibrationJSON, "rctrk", "test.rctrk", []byte{}, time.Now().Unix())
    94→	if err != nil {
    95→		t.Fatalf("seed spectra: %v", err)
    96→	}
    97→
    98→	// short_links
    99→	_, err = db.DB.ExecContext(ctx, `INSERT INTO short_links (code, target, created_at) VALUES (?, ?, ?)`,
   100→		testShortCode, testShortTarget, time.Now().Unix())
   101→	if err != nil {
   102→		t.Fatalf("seed short_links: %v", err)
   103→	}
   104→
   105→	// uploads
   106→	_, err = db.DB.ExecContext(ctx, `INSERT INTO uploads (filename, track_id, created_at, recording_date, username, detector) VALUES (?, ?, ?, ?, ?, ?)`,
   107→		"test.gpx", testTrackID, time.Now().Unix(), time.Now().Unix(), "testuser", "RadiaCode-102")
   108→	if err != nil {
   109→		t.Fatalf("seed uploads: %v", err)
   110→	}
   111→
   112→	// Verify seed: markers with has_spectrum should be visible
   113→	var count int
   114→	if err := db.DB.QueryRowContext(ctx, `SELECT COUNT(*) FROM markers WHERE has_spectrum = 1`).Scan(&count); err != nil {
   115→		t.Fatalf("verify seed: %v", err)
   116→	}
   117→	if count < 1 {
   118→		t.Fatalf("seed verification: expected at least 1 marker with has_spectrum, got %d", count)
   119→	}
   120→}
