   122→// --- QR handler tests ---
   123→
   124→func TestQRPng(t *testing.T) {
   125→	srv := newTestServer(t)
   126→
   127→	t.Run("with u param", func(t *testing.T) {
   128→		req := httptest.NewRequest(http.MethodGet, "/qrpng?u=https://example.com", nil)
   129→		rec := httptest.NewRecorder()
   130→		srv.qrPng(rec, req)
   131→		if rec.Code != http.StatusOK {
   132→			t.Errorf("got status %d, want 200", rec.Code)
   133→		}
   134→		if ct := rec.Header().Get("Content-Type"); ct != "image/png" {
   135→			t.Errorf("Content-Type = %q, want image/png", ct)
   136→		}
   137→		if len(rec.Body.Bytes()) < 100 {
   138→			t.Errorf("body too short for PNG")
   139→		}
   140→		// PNG magic bytes
   141→		if !bytes.HasPrefix(rec.Body.Bytes(), []byte{0x89, 0x50, 0x4e, 0x47}) {
   142→			t.Errorf("body is not valid PNG")
   143→		}
   144→	})
   145→
   146→	t.Run("with Referer header", func(t *testing.T) {
   147→		req := httptest.NewRequest(http.MethodGet, "/qrpng", nil)
   148→		req.Header.Set("Referer", "https://safecast.org/map")
   149→		rec := httptest.NewRecorder()
   150→		srv.qrPng(rec, req)
   151→		if rec.Code != http.StatusOK {
   152→			t.Errorf("got status %d, want 200", rec.Code)
   153→		}
   154→		if ct := rec.Header().Get("Content-Type"); ct != "image/png" {
   155→			t.Errorf("Content-Type = %q, want image/png", ct)
   156→		}
   157→	})
   158→
   159→	t.Run("builds URL from Host", func(t *testing.T) {
   160→		req := httptest.NewRequest(http.MethodGet, "/qrpng", nil)
   161→		req.Host = "example.com"
   162→		req.URL.Scheme = ""
   163→		rec := httptest.NewRecorder()
   164→		srv.qrPng(rec, req)
   165→		if rec.Code != http.StatusOK {
   166→			t.Errorf("got status %d, want 200", rec.Code)
   167→		}
   168→	})
   169→
   170→	t.Run("truncates long URL", func(t *testing.T) {
   171→		// URL over 4096 chars is truncated by handler
   172→		longURL := "https://example.com/" + strings.Repeat("a", 4100)
   173→		req := httptest.NewRequest(http.MethodGet, "/qrpng", nil)
   174→		req.URL.RawQuery = "u=" + longURL
   175→		rec := httptest.NewRecorder()
   176→		srv.qrPng(rec, req)
   177→		// Handler truncates to 4096; QR encode may fail for very long URLs (library limits)
   178→		if rec.Code != http.StatusOK && rec.Code != http.StatusInternalServerError {
   179→			t.Errorf("got status %d, want 200 or 500", rec.Code)
   180→		}
   181→	})
   182→}
