   391→func TestRequestClientIP(t *testing.T) {
   392→	tests := []struct {
   393→		name     string
   394→		forward  string
   395→		remote   string
   396→		want     string
   397→	}{
   398→		{"X-Forwarded-For", "10.0.0.1", "", "10.0.0.1"},
   399→		{"X-Forwarded-For multiple", "10.0.0.1, 192.168.1.1", "", "10.0.0.1"},
   400→		{"RemoteAddr", "", "192.168.1.1:12345", "192.168.1.1"},
   401→	}
   402→	for _, tt := range tests {
   403→		t.Run(tt.name, func(t *testing.T) {
   404→			req := httptest.NewRequest(http.MethodGet, "/", nil)
   405→			if tt.forward != "" {
   406→				req.Header.Set("X-Forwarded-For", tt.forward)
   407→			}
   408→			req.RemoteAddr = tt.remote
   409→			got := requestClientIP(req)
   410→			if got != tt.want {
   411→				t.Errorf("requestClientIP() = %q, want %q", got, tt.want)
   412→			}
   413→		})
   414→	}
   415→}
