package api

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"safecast-new-map/pkg/countryresolver"
	"safecast-new-map/pkg/database"
	"safecast-new-map/pkg/jsonarchive"
	"safecast-new-map/pkg/trackjson"
)

// =======================
// Public API entry points
// =======================

// Handler wires together the database and archive generator so HTTP routes
// can stay small and focused on translating query parameters into the
// asynchronous building blocks behind the scenes.
type Handler struct {
	DB               *database.Database
	DBType           string
	Archive          *jsonarchive.Generator
	ArchiveFrequency jsonarchive.Frequency
	Limiter          *RateLimiter
	Logf             func(string, ...any)
	Cache            *ResponseCache
	TrackInfo        *TrackInfoCache // Cache expensive COUNT(DISTINCT) metadata so /api stays fast even on huge datasets.
}

// NewHandler constructs a Handler with sane defaults.
// Logf is optional; pass nil if logging is not required.
func NewHandler(db *database.Database, dbType string, archive *jsonarchive.Generator, limiter *RateLimiter, logf func(string, ...any), freq jsonarchive.Frequency) *Handler {
	return &Handler{
		DB:               db,
		DBType:           dbType,
		Archive:          archive,
		ArchiveFrequency: freq,
		Limiter:          limiter,
		Logf:             logf,
		Cache:            NewResponseCache(24 * time.Hour),
		TrackInfo:        NewTrackInfoCache(db, dbType, 30*time.Minute, 5*time.Minute, 2*time.Minute, logf),
	}
}

// Register attaches API routes to the provided mux. We keep the method tiny
// and declarative: it simply wires URLs to helpers, avoiding clever routing
// that could obscure how pages are served.
func (h *Handler) Register(mux *http.ServeMux) {
	mux.HandleFunc("/api", h.handleOverview)
	mux.HandleFunc("/api/latest", h.handleLatestNearby)
	mux.HandleFunc("/api/tracks", h.handleTracksList)
	mux.HandleFunc("/api/tracks/index/", h.handleTrackDataByIndex)
	mux.HandleFunc("/api/tracks/years/", h.handleTracksByYear)
	mux.HandleFunc("/api/tracks/months/", h.handleTracksByMonth)
	mux.HandleFunc("/api/track/", h.handleTrackData)
	mux.HandleFunc("/api/tracks/", h.handleTrackData) // legacy alias for older clients
	mux.HandleFunc("/api/countries", h.handleCountries)
	mux.HandleFunc("/api/shorten", h.handleShorten)
	if h.Archive != nil {
		// Expose the tarball endpoint only when archive generation is enabled
		// so clients do not see a dangling route that always fails.
		route := h.ArchiveFrequency.RoutePath()
		if strings.TrimSpace(route) == "" {
			route = "/api/json/weekly.tgz"
		}
		mux.HandleFunc(route, h.handleArchiveDownload)
	}
}

// minimumDeadline ensures that API handlers give the serialized DB pipeline
// enough room to schedule work even when long TGZ imports are active. We avoid
// mutexes and rely on channels and context deadlines, so stretching the timer
// keeps single-writer engines responsive without masking client cancellations.
func minimumDeadline(ctx context.Context, min time.Duration) (context.Context, context.CancelFunc) {
	if ctx == nil {
		return context.WithTimeout(context.Background(), min)
	}
	if deadline, ok := ctx.Deadline(); ok {
		if time.Until(deadline) >= min {
			return ctx, func() {}
		}
		return context.WithTimeout(context.WithoutCancel(ctx), min)
	}
	return context.WithTimeout(ctx, min)
}

// acquirePermit enforces the per-IP rate limiter and writes an informative
// response if the caller exceeded their allowance. Returning false means the
// handler should stop processing because a response was already sent.
func (h *Handler) acquirePermit(w http.ResponseWriter, r *http.Request, kind RequestKind) (*Permit, bool) {
	if h.Limiter == nil {
		return nil, true
	}

	ip := clientIP(r)
	permit, err := h.Limiter.Acquire(r.Context(), ip, kind)
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			http.Error(w, "request cancelled", http.StatusRequestTimeout)
			return nil, false
		}
		http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
		if h.Logf != nil {
			h.Logf("rate limiter rejected %s %s: %v", ip, r.URL.Path, err)
		}
		return nil, false
	}

package auth

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"time"
)

const (
	// SessionDuration is the default duration for user sessions (30 days)
	SessionDuration = 30 * 24 * time.Hour

	// PasswordResetTokenDuration is how long password reset tokens are valid (1 hour)
	PasswordResetTokenDuration = 1 * time.Hour

	// EmailVerificationTokenDuration is how long email verification tokens are valid (24 hours)
	EmailVerificationTokenDuration = 24 * time.Hour
)

// RegisterHandler handles user registration requests.
// POST /api/auth/register
func (m *Manager) RegisterHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !m.AllowRegistration {
		writeJSONError(w, "Registration is currently disabled", http.StatusForbidden)
		return
	}

	var req struct {
		Email    string `json:"email"`
		Username string `json:"username"`
		Password string `json:"password"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSONError(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Validate inputs
	req.Email = NormalizeEmail(req.Email)
	if err := ValidateEmail(req.Email); err != nil {
		writeJSONError(w, err.Error(), http.StatusBadRequest)
		return
	}

	req.Username = SanitizeInput(req.Username)
	if err := ValidateUsername(req.Username); err != nil {
		writeJSONError(w, err.Error(), http.StatusBadRequest)
		return
	}

	if err := ValidatePassword(req.Password); err != nil {
		writeJSONError(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Check if user already exists
	existingUser, err := GetUserByEmail(r.Context(), m.DB, m.DBDriver, req.Email)
	if err != nil && err != sql.ErrNoRows {
		writeJSONError(w, "Database error", http.StatusInternalServerError)
		return
	}
	if existingUser != nil {
		writeJSONError(w, "Email address already registered", http.StatusConflict)
		return
	}

	// Create user
	user := &User{
		Email:         req.Email,
		Username:      req.Username,
		EmailVerified: false,
		IsActive:      true,
	}

	clientIP := getClientIP(r)
	userID, err := CreateUser(r.Context(), m.DB, m.DBDriver, user, req.Password)
	if err != nil {
		log.Printf("AUTH: Failed registration - email=%s username=%s reason=create_failed ip=%s error=%v", req.Email, req.Username, clientIP, err)
		writeJSONError(w, "Failed to create user", http.StatusInternalServerError)
		return
	}

	log.Printf("AUTH: New user registered - user_id=%d email=%s username=%s ip=%s", userID, req.Email, req.Username, clientIP)

	// Create email verification token
	token, err := GenerateToken()
	if err != nil {
		writeJSONError(w, "Failed to generate verification token", http.StatusInternalServerError)
		return
	}

package auth

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"

	"golang.org/x/crypto/bcrypt"
)

const (
	// BcryptCost is the cost factor for bcrypt hashing (higher = more secure but slower)
	BcryptCost = 12

	// TokenLength is the length of generated tokens in bytes (32 bytes = 256 bits)
	TokenLength = 32
)

// HashPassword hashes a password using bcrypt with the configured cost factor.
func HashPassword(password string) (string, error) {
	hashedBytes, err := bcrypt.GenerateFromPassword([]byte(password), BcryptCost)
	if err != nil {
		return "", fmt.Errorf("failed to hash password: %w", err)
	}
	return string(hashedBytes), nil
}

// VerifyPassword compares a plaintext password with a bcrypt hash.
// Returns true if the password matches the hash.
func VerifyPassword(hash, password string) bool {
	err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
	return err == nil
}

// GenerateToken generates a cryptographically secure random token.
// The token is base64-encoded for easy transmission in URLs and JSON.
func GenerateToken() (string, error) {
	bytes := make([]byte, TokenLength)
	if _, err := rand.Read(bytes); err != nil {
		return "", fmt.Errorf("failed to generate random token: %w", err)
	}
	return base64.URLEncoding.EncodeToString(bytes), nil
}

// GenerateSessionID generates a unique session ID.
// This is an alias for GenerateToken for clarity in code.
func GenerateSessionID() (string, error) {
	return GenerateToken()
}

// GenerateRandomPassword generates a random password of the specified length.
// Used for creating temporary passwords for migrated users.
func GenerateRandomPassword(length int) (string, error) {
	if length < 8 {
		length = 8
	}
	bytes := make([]byte, length)
	if _, err := rand.Read(bytes); err != nil {
		return "", fmt.Errorf("failed to generate random password: %w", err)
	}
	return base64.URLEncoding.EncodeToString(bytes)[:length], nil
}

