func TestLoginHandler(t *testing.T) {
	m := newTestManager(t)
	// Register once, reuse for all login sub-tests
	registerTestUser(t, m, "login@example.com", "loginuser", "Password123!")

	t.Run("GET returns 405", func(t *testing.T) {
